const EMPTY=Object.freeze([]);M.queryWalls=(x,y,r=0)=>{if(M.walls!==indexedWalls)return M.walls;let x0=Math.floor((x-r)/cell),x1=Math.floor((x+r)/cell),y0=Math.floor((y-r)/cell),y1=Math.floor((y+r)/cell);if(x0===x1&&y0===y1)return bins.get(binKey(x0,y0))||EMPTY;let result=null,first=null;for(let i=x0;i<=x1;i++)for(let j=y0;j<=y1;j++){let b=bins.get(binKey(i,j));if(!b)continue;if(!first){first=b;continue}if(!result)result=new Set(first);for(let w of b)result.add(w)}return result?[...result]:first||EMPTY};
