for(let [i,pit]of M.pits.entries()){pit.name=i?'巨龙巢穴':'虚空巢穴';M.camps.push({id:i?'DRAGON_PIT':'BARON_PIT',campId:i?'DRAGON_PIT':'BARON_PIT',kind:i?'dragon':'void',team:2,x:pit.x,y:pit.y,spawnPosition:{x:pit.x,y:pit.y},spawnRadius:pit.r*.65,leashRegion:{radius:650},monsterPositions:[],respawnTime:i?300:360,firstSpawn:i?300:360,campTerrainType:'EPIC_PIT',monsterNavigation:'TERRAIN_ASTAR',monsterAggroRange:500,monsterAttackRange:200,campCollision:'WORLD_POLYGONS'})}
