// V18 原创史诗目标「渊核祭坛」：两处河道祭坛（上/下半区，镜像对称），巨像每次刷新在两者之间轮换。
{let sites=[pt(907,955),pt(2400-907,2400-955)].map(p=>M.nearestLegal(p,175,900));if(sites.every(Boolean))M.camps.push({id:'COLOSSUS_ALTAR',campId:'COLOSSUS_ALTAR',kind:'colossus',team:2,...sites[0],sites,siteIndex:0,spawnPosition:{...sites[0]},spawnRadius:260,leashRegion:{radius:750},monsterPositions:[],respawnTime:420,firstSpawn:960,campTerrainType:'EPIC_ALTAR',monsterNavigation:'TERRAIN_ASTAR',monsterAggroRange:650,monsterAttackRange:380,campCollision:'WORLD_POLYGONS'})}
